func TestConfirmUntrustedIssueSeed_DeclinedExitsCleanly(t *testing.T) {
	t.Parallel()
	cmd := &cobra.Command{}
	var stderr bytes.Buffer
	cmd.SetErr(&stderr)
	cmd.SetOut(&stderr)

	deps := Deps{
