	require.Equal(t,
		filepath.Join(commonDir, "entire-investigations", "bbbbbbbbbbbb", "findings.md"),
		findings2,
	)
	require.NotEqual(t, findings1, findings2,
		"two runs must not share findings doc paths")
}

