12	// withFakeGh swaps runGhFn for the duration of the test.
13	//
14	// runGhFn is a package-level variable, so tests that override it cannot run
15	// in parallel with each other — calling t.Parallel inside a test that uses
16	// withFakeGh would race with sibling tests' overrides. The CLAUDE.md project
17	// rule allows skipping t.Parallel when tests modify process-global state;
18	// runGhFn falls into that bucket.
19	func withFakeGh(t *testing.T, fake func(ctx context.Context, args ...string) ([]byte, error)) {
20		t.Helper()
21		prev := runGhFn
22		runGhFn = fake
23		t.Cleanup(func() { runGhFn = prev })
24	}
