26	// fakeGhSuccess returns the given response unconditionally and asserts that
27	// the gh subcommand matches expectedSubcommand.
28	func fakeGhSuccess(t *testing.T, expectedSubcommand string, response any) func(ctx context.Context, args ...string) ([]byte, error) {
29		t.Helper()
30		return func(_ context.Context, args ...string) ([]byte, error) {
31			if len(args) == 0 || args[0] != expectedSubcommand {
32				t.Errorf("expected subcommand %q, got args=%v", expectedSubcommand, args)
33			}
34			return json.Marshal(response)
35		}
36	}
